def longest_stop_free(sequence, strand):
    N=len(sequence); best=[]
    for frame in range(3):
        run_start=frame
        i=frame
        while i<N-2:
            if sequence[i:i+3] in stops:
                length=(i-run_start)
                if length>0: best.append((run_start,i,length,strand,frame))
                run_start=i+3
            i+=3
        # tail
        if N-2-run_start>0:
            best.append((run_start,N, N-2-run_start, strand, frame))
    return best

