import random, statistics
seq = ""
with open('region.fasta') as f:
    for line in f:
        if not line.startswith('>'):
            seq += line.strip().upper()
n=len(seq)
comp=str.maketrans('ACGT','TGCA')
def revcomp(s): return s.translate(comp)[::-1]
stops={'TAA','TAG','TGA'}

def top_stretches(sequence, k=6):
    N=len(sequence); runs=[]
    for s in (sequence, revcomp(sequence)):
        for frame in range(3):
            run=0
            for i in range(frame, N-2, 3):
                if s[i:i+3] in stops:
                    runs.append(run); run=0
                else:
                    run+=1
            runs.append(run)
    runs.sort(reverse=True)
    return runs[:k]

obs = top_stretches(seq)
print("observed top stop-free stretches (codons):", obs)

letters=list(seq)
random.seed(2)
sims={i:[] for i in range(6)}
for t in range(1000):
    random.shuffle(letters)
    ts=top_stretches(''.join(letters))
    for i in range(6): sims[i].append(ts[i])
for i in range(6):
    s=sorted(sims[i])
    p=sum(1 for x in s if x>=obs[i])/len(s)
    print(f"  rank{i+1}: observed={obs[i]:4d}  null_mean={statistics.mean(s):.1f}  95th={s[950]}  frac_null>=obs={p:.4f}")
